-- Empty-database foundation for Community 0.1.
-- The timestamped ledger assumes the core GORM tables already exist.
-- Existing deployments are deliberately untouched. Captured from the core API
-- model list on 2026-09-15 with transitional names/columns needed by the ledger.
-- Later model changes require a new migration; do not regenerate this snapshot.
DO $community_foundation$
BEGIN
 IF to_regclass('public.users') IS NOT NULL AND to_regclass('public.workspaces') IS NOT NULL THEN
  RETURN;
 END IF;
 IF to_regclass('public.users') IS NOT NULL OR to_regclass('public.workspaces') IS NOT NULL THEN
  RAISE EXCEPTION 'incomplete base schema; restore a complete database before migrating';
 END IF;
 IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name <> 'schema_migrations') THEN
  RAISE EXCEPTION 'base schema missing in a non-empty database; refusing to bootstrap';
 END IF;
 EXECUTE $core_schema$
CREATE TABLE "users" ("id" uuid DEFAULT gen_random_uuid(),"email" text NOT NULL,"password_hash" text NOT NULL,"full_name" text NOT NULL,"email_verified_at" timestamptz,"google_subject" text,"avatar_url" text,"avatar_style" text,"avatar_seed" text,"avatar_background_mode" text,"avatar_background_color" text,"default_workspace_id" uuid,"totp_secret_encrypted" text,"totp_verified" boolean NOT NULL DEFAULT false,"recovery_codes_encrypted" text,"is_platform_admin" boolean NOT NULL DEFAULT false,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_google_subject" ON "users" ("google_subject");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE TABLE "user_passkeys" ("id" uuid DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL,"credential_id" bytea NOT NULL,"public_key" bytea NOT NULL,"attestation_type" text NOT NULL,"transport" jsonb NOT NULL DEFAULT '[]',"sign_count" bigint NOT NULL DEFAULT 0,"name" text NOT NULL,"aaguid" bytea,"flags" bigint NOT NULL DEFAULT 0,"verified" boolean NOT NULL DEFAULT false,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
