CREATE INDEX IF NOT EXISTS "idx_support_content_chunks_section_key" ON "support_content_chunks" ("section_key");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_support_content_chunk_page_order" ON "support_content_chunks" ("page_id","chunk_index");
CREATE INDEX IF NOT EXISTS "idx_support_content_chunks_content_source_id" ON "support_content_chunks" ("content_source_id");
CREATE INDEX IF NOT EXISTS "idx_support_content_chunk_ws_source_page" ON "support_content_chunks" ("workspace_id","content_source_id","page_id");
CREATE TABLE "curated_guidance" ("id" uuid DEFAULT gen_random_uuid(),"workspace_id" uuid NOT NULL,"agent_id" uuid NOT NULL,"title" text NOT NULL,"question_patterns" text[],"answer" text NOT NULL,"intent" text NOT NULL DEFAULT 'unknown',"topics" text[],"language" text NOT NULL DEFAULT '',"audience_policy_id" uuid,"brand_id" uuid,"status" text NOT NULL DEFAULT 'active',"valid_from" timestamptz,"valid_until" timestamptz,"embedding" vector(1536),"embedding_provider" text,"embedding_model" text,"embedding_version" text,"embedding_dimensions" bigint,"created_by_id" uuid NOT NULL,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_valid_until" ON "curated_guidance" ("valid_until");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_valid_from" ON "curated_guidance" ("valid_from");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_brand_id" ON "curated_guidance" ("brand_id");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_audience_policy_id" ON "curated_guidance" ("audience_policy_id");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_language" ON "curated_guidance" ("language");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_intent" ON "curated_guidance" ("intent");
CREATE INDEX IF NOT EXISTS "idx_curated_guidance_scope" ON "curated_guidance" ("workspace_id","agent_id","status");

